import heapq
from collections import Counter


def min_cpu_intervals(tasks, n):
    if not tasks:
        return 0
    counts = Counter(tasks)
    heap = [-c for c in counts.values()]
    heapq.heapify(heap)
    time = 0
    while heap:
        buffer = []
        for _ in range(n + 1):
            if heap:
                cnt = heapq.heappop(heap)
                if cnt + 1 < 0:
                    buffer.append(cnt + 1)
            time += 1
            if not heap and not buffer:
                break
        for c in buffer:
            heapq.heappush(heap, c)
    return time
